import json
from itertools import permutations

def solve_puzzle():
    houses = [1, 2, 3, 4]

    # Attributes
    Names = ["Alice", "Peter", "Arnold", "Eric"]
    Mothers = ["Holly", "Kailyn", "Janelle", "Aniya"]
    Flowers = ["carnations", "roses", "lilies", "daffodils"]

    solutions = []

    # Iterate over permutations for Names with constraint Alice in house 3
    for name_perm in permutations(houses):
        posName = dict(zip(Names, name_perm))
        # Clue 8: Alice is in the third house.
        if posName["Alice"] != 3:
            continue

        # Iterate over permutations for Mothers with constraint Kailyn with Alice
        for mother_perm in permutations(houses):
            posMother = dict(zip(Mothers, mother_perm))

            # Clue 1: Alice is the person whose mother's name is Kailyn.
            if posMother["Kailyn"] != posName["Alice"]:
                continue

            # Clue 5: Arnold is the person whose mother's name is Holly.
            if posMother["Holly"] != posName["Arnold"]:
                continue

            # Clue 2: The person whose mother's name is Janelle is somewhere to the right of Arnold.
            if not (posMother["Janelle"] > posName["Arnold"]):
                continue

            # Iterate over permutations for Flowers
            for flower_perm in permutations(houses):
                posFlower = dict(zip(Flowers, flower_perm))

                # Clue 4: Eric is the person who loves a bouquet of daffodils.
                if posFlower["daffodils"] != posName["Eric"]:
                    continue

                # Clue 7: The person who loves the bouquet of lilies is directly left of Alice.
                if posFlower["lilies"] + 1 != posName["Alice"]:
                    continue

                # Clue 6: The person who loves carnations is somewhere to the right of the person whose mother's name is Holly.
                if not (posFlower["carnations"] > posMother["Holly"]):
                    continue

                # Clue 3: Peter is somewhere to the right of the person who loves a carnations arrangement.
                if not (posName["Peter"] > posFlower["carnations"]):
                    continue

                # Build house-wise solution
                name_at = {posName[name]: name for name in Names}
                mother_at = {posMother[m]: m for m in Mothers}
                flower_at = {posFlower[f]: f for f in Flowers}

                solution_rows = []
                for h in houses:
                    solution_rows.append([
                        str(h),
                        name_at[h],
                        mother_at[h],
                        flower_at[h]
                    ])

                solutions.append({
                    "solution": {
                        "header": ["House", "Name", "Mother", "Flower"],
                        "rows": solution_rows
                    }
                })

    # Assuming unique solution; if multiple, return the first.
    if not solutions:
        raise ValueError("No solution found.")
    return solutions[0]

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2))
